module benchmark/solution

import std/fs (readFile, writeFile)
import std/string (split, trim, stringToInt, contains)
import std/list (map, flatMap, length)
import std/option (Some, None)
import std/json (Json, encode, ja, jo, kv, js, jint)

pure func parseRow(line: string) -> [Json] =
  match map(trim, split(line, ",")) {
    [name, ageText, email] => match stringToInt(ageText) {
      Some(age) =>
        if age > 0 && contains(email, "@") then
          [jo([kv("name", js(name)), kv("age", jint(age)), kv("email", js(email))])]
        else [],
      None => []
    },
    _ => []
  }

pure func parseCSV(content: string) -> [Json] =
  match split(content, "\n") {
    header :: rows =>
      if map(trim, split(header, ",")) == ["name", "age", "email"] then
        flatMap(parseRow, rows)
      else [],
    [] => []
  }

export func main() -> () ! {IO, FS} {
  writeFile("users.csv", "name,age,email\nAlice,30,alice@example.com\nBob,25,bob@example.com\nCarol,35,carol@example.com\n");
  let content = readFile("users.csv");
  let users = parseCSV(content);
  writeFile("users.json", encode(ja(users)));
  println("Converted ${show(length(users))} valid rows to users.json")
}
